import { axiosInstance, backendBaseURL } from "./backendClient";
export async function getAllDesigners() {
    return (await axiosInstance.get(`${backendBaseURL}/api/designers`)).data;
}
export async function searchDesigners(query) {
    return (await axiosInstance.get(`${backendBaseURL}/api/designers/search`, { params: { query } })).data;
}
export async function createDesigner(designer) {
    return (await axiosInstance.post(`${backendBaseURL}/api/designers/add/designer`, designer)).data;
}
