import { useEffect, useState } from "react";
export function useModelPreviewUrl(image) {
    const [url, setUrl] = useState();
    useEffect(() => {
        if (typeof image === "string") {
            setUrl(image);
            return;
        }
        if (!image) {
            setUrl(undefined);
            return;
        }
        const nextUrl = URL.createObjectURL(image);
        setUrl(nextUrl);
        return () => URL.revokeObjectURL(nextUrl);
    }, [image]);
    return url;
}
