import { bearerHeaders, csrfHeaders, javaApi } from '../../apis/client';
export async function registerUser(profile) {
    const { data } = await javaApi.post('/api/register', profile, { headers: await csrfHeaders() });
    return data;
}
export async function syncCurrentUser(token) {
    const { data } = await javaApi.get('/api/me', { headers: bearerHeaders(token) });
    return toUserProfile(data);
}
export async function updateCurrentUser(token, profile) {
    const { data } = await javaApi.put('/api/me', profile, {
        headers: { ...bearerHeaders(token), ...(await csrfHeaders()) },
    });
    return toUserProfile(data);
}
function toUserProfile(user) {
    return {
        ...user,
        username: user.username ?? user.displayName ?? '',
    };
}
