import { csrfHeaders } from "@/apis/client";
import { axiosInstance, backendBaseURL } from "./backendClient";
export async function getAboutContent() {
    return (await axiosInstance.get(`${backendBaseURL}/api/about`)).data;
}
export async function updateAboutContent(content) {
    return (await axiosInstance.put(`${backendBaseURL}/api/about`, { content }, { headers: await csrfHeaders() })).data;
}
export async function getStoreLocation() {
    return (await axiosInstance.get(`${backendBaseURL}/api/location`)).data;
}
export async function updateStoreLocation(location) {
    return (await axiosInstance.put(`${backendBaseURL}/api/location`, location)).data;
}
