import { axiosInstance, backendBaseURL } from "./backendClient";
function fileToBase64(file) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => {
            if (typeof reader.result !== "string" || !reader.result.split(",")[1])
                return reject(new Error("Invalid base64 image data"));
            resolve(reader.result.split(",")[1]);
        };
        reader.onerror = () => reject(reader.error ?? new Error("Failed to read image"));
        reader.readAsDataURL(file);
    });
}
export async function saveAntiqueReconstruction(id, views, modelUrl) {
    const reconstructionViews = await Promise.all(views.map(async ({ position, image_data }) => ({
        position, imageData: await fileToBase64(image_data), contentType: image_data.type,
    })));
    const response = await axiosInstance.put(`${backendBaseURL}/api/antiques/${id}/reconstruction`, {
        views: reconstructionViews, modelUrl: modelUrl ?? null,
    });
    return response.data;
}
export async function getAntiqueReconstructionImages(id) {
    const response = await axiosInstance.get(`${backendBaseURL}/api/antiques/${id}/reconstruction`);
    return response.data;
}
