import axios from "axios";
const reconstructionBaseUrl = import.meta.env.VITE_RECONSTRUCTION_API_URL ?? "http://localhost:8000";
const reconstructionClient = axios.create({
    baseURL: reconstructionBaseUrl,
    timeout: 30000,
    withCredentials: false,
});
export async function createReconstructionJob(antiqueId, images) {
    const body = new FormData();
    body.append("antique_id", antiqueId);
    images.forEach(({ position, file }) => {
        body.append("images", file);
        body.append("positions", position);
    });
    const response = await reconstructionClient.post("/v1/reconstructions", body);
    return response.data;
}
export async function getReconstructionJob(jobId) {
    const response = await reconstructionClient.get(`/v1/reconstructions/${jobId}`);
    return response.data;
}
