import { axiosInstance, backendBaseURL } from "./backendClient";
export async function getVisibleCategories() {
    return (await axiosInstance.get(`${backendBaseURL}/api/categories`)).data;
}
export async function getAllCategories() {
    return (await axiosInstance.get(`${backendBaseURL}/api/categories/admin`)).data;
}
export async function updateCategory(category) {
    return (await axiosInstance.put(`${backendBaseURL}/api/categories/${category.id}`, {
        name: category.name, parentId: category.parentId ?? null, visible: category.visible,
    })).data;
}
export async function createCategory(name, parentId) {
    return (await axiosInstance.post(`${backendBaseURL}/api/categories`, {
        name, parentId: parentId || null, visible: true,
    })).data;
}
export async function deleteCategory(id) {
    await axiosInstance.delete(`${backendBaseURL}/api/categories/${id}`);
}
