import { axiosInstance, backendBaseURL } from "./backendClient";
export async function getAllAntiques() {
    const response = await axiosInstance.get(`${backendBaseURL}/api/antiques`);
    const payload = response.data;
    return Array.isArray(payload) ? payload : payload.content ?? payload.antiques ?? payload.data ?? [];
}
export async function addAntique(antique) {
    const response = await axiosInstance.post(`${backendBaseURL}/api/antiques`, antique);
    return response.data;
}
export async function uploadAntiqueImage(id, image) {
    const body = new FormData();
    body.append("image", image);
    await axiosInstance.put(`${backendBaseURL}/api/antiques/${id}/image`, body, { headers: { "Content-Type": undefined } });
}
